1 | /**
2 |  * BugSleuth frontend — handles form submission, demo loading, and report rendering.
3 |  * API shape matches the run_investigation() response from investigation_service.py.
4 |  */
5 | 
6 | document.addEventListener("DOMContentLoaded", () => {
7 |   const btnInvestigate = document.getElementById("btn-investigate");
8 |   const btnDemo        = document.getElementById("btn-demo");
9 |   if (btnInvestigate) btnInvestigate.addEventListener("click", runInvestigation);
10 |   if (btnDemo)        btnDemo.addEventListener("click", runDemo);
11 | });
12 | 
13 | // ---------------------------------------------------------------------------
14 | // API calls
15 | // ---------------------------------------------------------------------------
16 | 
17 | async function runDemo() {
18 |   showSpinner();
19 |   try {
20 |     const res  = await fetch("/api/investigate", { method: "POST" });
21 |     const data = await res.json();
22 |     if (data.error) throw new Error(data.error);
23 |     renderReport(data);
24 |   } catch (err) {
25 |     showError(err.message);
26 |   }
27 | }
28 | 
29 | async function runInvestigation() {
30 |   showSpinner();
31 | 
32 |   const formData = new FormData();
33 |   const observation = val("observation");
34 |   const github_url  = val("github_repo_url");
35 | 
36 |   if (!observation && !github_url) {
37 |     const logFile    = document.getElementById("logs")    && document.getElementById("logs").files[0];
38 |     const sourceFile = document.getElementById("source_zip") && document.getElementById("source_zip").files[0];
39 |     if (!logFile && !sourceFile && !observation && !github_url) {
40 |       showError("Please provide at least one piece of evidence before running an investigation.");
41 |       return;
42 |     }
43 |   }
44 | 
45 |   if (observation)  formData.append("observation",     observation);
46 |   if (github_url)   formData.append("github_repo_url", github_url);
47 | 
48 |   const logFile    = document.getElementById("logs")        ? document.getElementById("logs").files[0]        : null;
49 |   const sourceFile = document.getElementById("source_zip")  ? document.getElementById("source_zip").files[0]  : null;
50 |   if (logFile)    formData.append("logs",        logFile);
51 |   if (sourceFile) formData.append("source_zip",  sourceFile);
52 | 
53 |   try {
54 |     // Step 1: create investigation
55 |     const createRes = await fetch("/api/investigations", { method: "POST", body: formData });
56 |     const createData = await createRes.json();
57 |     if (!createRes.ok) throw new Error(createData.error || "Failed to create investigation.");
58 | 
59 |     const investigationId = createData.investigation_id;
60 | 
61 |     // Step 2: run investigation
62 |     const runRes  = await fetch(`/api/investigations/${investigationId}/run`, { method: "POST" });
63 |     const runData = await runRes.json();
64 |     if (!runRes.ok) throw new Error(runData.error || "Investigation failed.");
65 | 
66 |     renderReport(runData);
67 |   } catch (err) {
68 |     showError(err.message);
69 |   }
70 | }
71 | 
72 | // ---------------------------------------------------------------------------
73 | // Report rendering
74 | // ---------------------------------------------------------------------------
75 | 
76 | function renderReport(d) {
77 |   const panel = document.getElementById("report");
78 |   panel.innerHTML = `
79 |     ${renderPipeline()}
80 |     ${renderIncidentHeader(d)}
81 |     ${renderInvestigators(d.investigators)}
82 |     ${renderTribunal(d.tribunal)}
83 |     ${renderVerdict(d.tribunal && d.tribunal.judge)}
84 |     ${renderActions(d.recommended_actions)}
85 |     ${renderDownloadButton(d._investigation_id)}
86 |   `;
87 |   setButtons(false);
88 | }
89 | 
90 | function renderPipeline() {
91 |   const steps = ["Incident", "Evidence", "Tribunal", "Verdict", "Proof"];
92 |   return `<div class="pipeline">${steps.map(s => `<div class="step done">${s}</div>`).join("")}</div>`;
93 | }
94 | 
95 | function renderIncidentHeader(d) {
96 |   const inc = d.incident || {};
97 |   return `
98 |     <div class="card">
99 |       <div class="card-title">Incident</div>
100 |       <p><strong>${esc(inc.title || inc.service || "Investigation")}</strong></p>
101 |       <p style="margin-top:6px;font-size:13px;color:#94a3b8">${esc(inc.description || inc.error_summary || "")}</p>
102 |       <p style="margin-top:8px;font-size:12px;color:#64748b">
103 |         Service: ${esc(inc.service || "—")} &nbsp;·&nbsp;
104 |         Severity: ${esc(inc.severity || "—")} &nbsp;·&nbsp;
105 |         Mode: <span style="color:#a78bfa">${esc(d.mode || "user")}</span>
106 |       </p>
107 |     </div>`;
108 | }
109 | 
110 | function renderInvestigators(investigators) {
111 |   if (!investigators || !investigators.length) return "";
112 |   const cards = investigators.map(inv => {
113 |     const pct = Math.round((inv.confidence || 0) * 100);
114 |     const statusColor = inv.status === "complete" ? "#4ade80" : "#f87171";
115 |     return `
116 |       <div class="evidence-card">
117 |         <div class="eid" style="color:${statusColor}">${esc(inv.agent)}</div>
118 |         <div style="font-size:11px;color:#64748b;margin-bottom:6px">${esc(inv.status)}</div>
119 |         ${(inv.findings || []).map(f => `<div class="finding" style="font-size:12px;margin-bottom:3px">· ${esc(f)}</div>`).join("")}
120 |         <div class="conf-bar" style="margin-top:8px">
121 |           <div class="conf-fill" style="width:${pct}%"></div>
122 |         </div>
123 |         <div style="font-size:11px;color:#475569;margin-top:4px">confidence ${pct}%</div>
124 |       </div>`;
125 |   }).join("");
126 |   return `
127 |     <div class="card">
128 |       <div class="card-title">Investigators (Parallel)</div>
129 |       <div class="evidence-grid">${cards}</div>
130 |     </div>`;
131 | }
132 | 
133 | function renderTribunal(tribunal) {
134 |   if (!tribunal) return "";
135 |   const p = tribunal.prosecutor || {};
136 |   const d = tribunal.defense    || {};
137 |   return `
138 |     <div class="card">
139 |       <div class="card-title">Tribunal</div>
140 |       <div class="tribunal-grid">
141 |         <div>
142 |           <div class="role-label role-prosecutor">⚖ Prosecutor</div>
143 |           <p style="font-size:13px;margin-bottom:6px"><strong>${esc(p.position || "")}</strong></p>
144 |           <p style="font-size:12px;color:#94a3b8">${esc(p.argument || "")}</p>
145 |         </div>
146 |         <div class="tribunal-divider"></div>
147 |         <div>
148 |           <div class="role-label role-defense">🛡 Defense</div>
149 |           <p style="font-size:13px;margin-bottom:6px"><strong>${esc(d.argument || "")}</strong></p>
150 |           <ul style="margin-top:8px;padding-left:16px;font-size:11px;color:#64748b">
151 |             ${(d.missing_evidence || []).map(w => `<li>${esc(w)}</li>`).join("")}
152 |           </ul>
153 |         </div>
154 |       </div>
155 |     </div>`;
156 | }
157 | 
158 | function renderVerdict(verdict) {
159 |   if (!verdict) return "";
160 |   const status = verdict.verdict || "UNKNOWN";
161 |   const statusClass = {
162 |     "CONFIRMED":             "verdict-CONFIRMED",
163 |     "MOST_LIKELY":           "verdict-MOST_LIKELY",
164 |     "MORE_EVIDENCE_NEEDED":  "verdict-MORE_EVIDENCE_NEEDED",
165 |     "REJECTED":              "verdict-REJECTED",
166 |   }[status] || "verdict-MORE_EVIDENCE_NEEDED";
167 | 
168 |   const steps = (verdict.recommended_next_steps || [])
169 |     .map(s => `<li>${esc(s)}</li>`).join("");
170 | 
171 |   return `
172 |     <div class="card">
173 |       <div class="card-title">Verdict — Judge</div>
174 |       <div class="verdict-badge ${statusClass}">${status.replace(/_/g, " ")}</div>
175 |       <p style="font-weight:600;margin-bottom:8px">${esc(verdict.leading_hypothesis || "")}</p>
176 |       <p style="font-size:13px;color:#94a3b8">${esc(verdict.best_current_assessment || verdict.reason || "")}</p>
177 |       <p style="font-size:12px;color:#475569;margin-top:8px">
178 |         Confidence: <strong>${esc(verdict.confidence_level || "")}</strong>
179 |       </p>
180 |       ${steps ? `<ul class="actions-list" style="margin-top:12px">${steps}</ul>` : ""}
181 |     </div>`;
182 | }
183 | 
184 | function renderActions(actions) {
185 |   if (!actions) return "";
186 |   const all = [
187 |     ...(actions.high_priority   || []),
188 |     ...(actions.medium_priority || []),
189 |     ...(actions.optional        || []),
190 |   ];
191 |   if (!all.length) return "";
192 |   const items = all.map(a => `<li><strong>[${esc(a.priority)}]</strong> ${esc(a.action)}</li>`).join("");
193 |   return `
194 |     <div class="card">
195 |       <div class="card-title">Recommended Actions</div>
196 |       <ul class="actions-list">${items}</ul>
197 |     </div>`;
198 | }
199 | 
200 | function renderDownloadButton(investigationId) {
201 |   if (!investigationId) return "";
202 |   const url = `/api/investigations/${encodeURIComponent(investigationId)}/report`;
203 |   return `
204 |     <div style="margin-top:8px;margin-bottom:24px">
205 |       <a href="${url}" download class="btn btn-download" id="btn-download-report"
206 |          style="display:inline-block;width:auto;padding:10px 22px;text-decoration:none;">
207 |         ⬇ Download Report
208 |       </a>
209 |     </div>`;
210 | }
211 | 
212 | // ---------------------------------------------------------------------------
213 | // UI helpers
214 | // ---------------------------------------------------------------------------
215 | 
216 | function showSpinner() {
217 |   const panel = document.getElementById("report");
218 |   panel.innerHTML = `
219 |     <div id="spinner" class="active">
220 |       <div class="spin-ring"></div>
221 |       <span style="color:#64748b;font-size:13px">Running investigation…</span>
222 |     </div>`;
223 |   setButtons(true);
224 | }
225 | 
226 | function showError(msg) {
227 |   document.getElementById("report").innerHTML = `
228 |     <div class="card" style="border-color:#7f1d1d">
229 |       <div class="card-title" style="color:#f87171">Error</div>
230 |       <p style="color:#fca5a5">${esc(msg)}</p>
231 |     </div>`;
232 |   setButtons(false);
233 | }
234 | 
235 | function setButtons(disabled) {
236 |   ["btn-investigate", "btn-demo"].forEach(id => {
237 |     const el = document.getElementById(id);
238 |     if (el) el.disabled = disabled;
239 |   });
240 | }
241 | 
242 | function esc(str) {
243 |   if (str === null || str === undefined) return "";
244 |   return String(str)
245 |     .replace(/&/g, "&amp;")
246 |     .replace(/</g, "&lt;")
247 |     .replace(/>/g, "&gt;")
248 |     .replace(/"/g, "&quot;");
249 | }
250 | 
251 | function val(id) {
252 |   const el = document.getElementById(id);
253 |   return el ? (el.value || "").trim() : "";
254 | }
255 |

