2 |  * BugSleuth frontend — handles form submission, demo loading, and report rendering.
3 |  * API shape matches the run_investigation() response from investigation_service.py.
4 |  */
5 | 
6 | document.addEventListener("DOMContentLoaded", () => {
7 |   const btnInvestigate = document.getElementById("btn-investigate");
8 |   const btnDemo        = document.getElementById("btn-demo");
9 |   if (btnInvestigate) btnInvestigate.addEventListener("click", runInvestigation);
10 |   if (btnDemo)        btnDemo.addEventListener("click", runDemo);
11 | });
