13 | // ---------------------------------------------------------------------------
14 | // API calls
15 | // ---------------------------------------------------------------------------
16 | 
17 | async function runDemo() {
18 |   showSpinner();
19 |   try {
20 |     const res  = await fetch("/api/investigate", { method: "POST" });
21 |     const data = await res.json();
22 |     if (data.error) throw new Error(data.error);
23 |     renderReport(data);
24 |   } catch (err) {
25 |     showError(err.message);
26 |   }
27 | }
28 | 
29 | async function runInvestigation() {
30 |   showSpinner();
31 | 
32 |   const formData = new FormData();
33 |   const observation = val("observation");
34 |   const github_url  = val("github_repo_url");
35 | 
36 |   if (!observation && !github_url) {
37 |     const logFile    = document.getElementById("logs")    && document.getElementById("logs").files[0];
38 |     const sourceFile = document.getElementById("source_zip") && document.getElementById("source_zip").files[0];
39 |     if (!logFile && !sourceFile && !observation && !github_url) {
40 |       showError("Please provide at least one piece of evidence before running an investigation.");
41 |       return;
42 |     }
43 |   }
44 | 
45 |   if (observation)  formData.append("observation",     observation);
46 |   if (github_url)   formData.append("github_repo_url", github_url);
47 | 
48 |   const logFile    = document.getElementById("logs")        ? document.getElementById("logs").files[0]        : null;
