      <p style="margin-top:6px;font-size:13px;color:#94a3b8">${esc(inc.description || inc.error_summary || "")}</p>
      <p style="margin-top:8px;font-size:12px;color:#64748b">
        Service: ${esc(inc.service || "—")} &nbsp;·&nbsp;
        Severity: ${esc(inc.severity || "—")} &nbsp;·&nbsp;
        Mode: <span style="color:#a78bfa">${esc(d.mode || "user")}</span>
      </p>
    </div>`;
}

function renderInvestigators(investigators) {
  if (!investigators || !investigators.length) return "";
  const cards = investigators.map(inv => {
    const pct = Math.round((inv.confidence || 0) * 100);
    const statusColor = inv.status === "complete" ? "#4ade80" : "#f87171";
    return `
      <div class="evidence-card">
        <div class="eid" style="color:${statusColor}">${esc(inv.agent)}</div>
        <div style="font-size:11px;color:#64748b;margin-bottom:6px">${esc(inv.status)}</div>
        ${(inv.findings || []).map(f => `<div class="finding" style="font-size:12px;margin-bottom:3px">· ${esc(f)}</div>`).join("")}
        <div class="conf-bar" style="margin-top:8px">
          <div class="conf-fill" style="width:${pct}%"></div>
        </div>
        <div style="font-size:11px;color:#475569;margin-top:4px">confidence ${pct}%</div>
      </div>`;
  }).join("");
  return `
    <div class="card">
      <div class="card-title">Investigators (Parallel)</div>
      <div class="evidence-grid">${cards}</div>
    </div>`;
}

function renderTribunal(tribunal) {
  if (!tribunal) return "";
  const p = tribunal.prosecutor || {};
  const d = tribunal.defense    || {};
  return `
    <div class="card">
      <div class="card-title">Tribunal</div>
      <div class="tribunal-grid">
        <div>
          <div class="role-label role-prosecutor">⚖ Prosecutor</div>
          <p style="font-size:13px;margin-bottom:6px"><strong>${esc(p.position || "")}</strong></p>
          <p style="font-size:12px;color:#94a3b8">${esc(p.argument || "")}</p>
        </div>
        <div class="tribunal-divider"></div>
        <div>
          <div class="role-label role-defense">🛡 Defense</div>
          <p style="font-size:13px;margin-bottom:6px"><strong>${esc(d.argument || "")}</strong></p>
          <ul style="margin-top:8px;padding-left:16px;font-size:11px;color:#64748b">
            ${(d.missing_evidence || []).map(w => `<li>${esc(w)}</li>`).join("")}
          </ul>
        </div>
      </div>
    </div>`;
}

function renderVerdict(verdict) {
  if (!verdict) return "";
  const status = verdict.verdict || "UNKNOWN";
  const statusClass = {
    "CONFIRMED":             "verdict-CONFIRMED",
    "MOST_LIKELY":           "verdict-MOST_LIKELY",
    "MORE_EVIDENCE_NEEDED":  "verdict-MORE_EVIDENCE_NEEDED",
    "REJECTED":              "verdict-REJECTED",
  }[status] || "verdict-MORE_EVIDENCE_NEEDED";

  const steps = (verdict.recommended_next_steps || [])
    .map(s => `<li>${esc(s)}</li>`).join("");

  return `
    <div class="card">
      <div class="card-title">Verdict — Judge</div>
      <div class="verdict-badge ${statusClass}">${status.replace(/_/g, " ")}</div>
      <p style="font-weight:600;margin-bottom:8px">${esc(verdict.leading_hypothesis || "")}</p>
      <p style="font-size:13px;color:#94a3b8">${esc(verdict.best_current_assessment || verdict.reason || "")}</p>
      <p style="font-size:12px;color:#475569;margin-top:8px">
        Confidence: <strong>${esc(verdict.confidence_level || "")}</strong>
      </p>
      ${steps ? `<ul class="actions-list" style="margin-top:12px">${steps}</ul>` : ""}
    </div>`;
}

function renderActions(actions) {
  if (!actions) return "";
  const all = [
    ...(actions.high_priority   || []),
    ...(actions.medium_priority || []),
    ...(actions.optional        || []),
  ];
  if (!all.length) return "";
  const items = all.map(a => `<li><strong>[${esc(a.priority)}]</strong> ${esc(a.action)}</li>`).join("");
  return `
    <div class="card">
      <div class="card-title">Recommended Actions</div>
      <ul class="actions-list">${items}</ul>
    </div>`;
}

function renderDownloadButton(investigationId) {
  if (!investigationId) return "";
  const url = `/api/investigations/${encodeURIComponent(investigationId)}/report`;
  return `
    <div style="margin-top:8px;margin-bottom:24px">
      <a href="${url}" download class="btn btn-download" id="btn-download-report"
         style="display:inline-block;width:auto;padding:10px 22px;text-decoration:none;">
        ⬇ Download Report
      </a>
    </div>`;
}

// ---------------------------------------------------------------------------
// UI helpers
// ---------------------------------------------------------------------------

function showSpinner() {
  const panel = document.getElementById("report");
  panel.innerHTML = `
    <div id="spinner" class="active">
      <div class="spin-ring"></div>
      <span style="color:#64748b;font-size:13px">Running investigation…</span>
    </div>`;
  setButtons(true);
}

function showError(msg) {
  document.getElementById("report").innerHTML = `
    <div class="card" style="border-color:#7f1d1d">
      <div class="card-title" style="color:#f87171">Error</div>
      <p style="color:#fca5a5">${esc(msg)}</p>
    </div>`;
  setButtons(false);
}

function setButtons(disabled) {
  ["btn-investigate", "btn-demo"].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.disabled = disabled;
  });
}

function esc(str) {
  if (str === null || str === undefined) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function val(id) {
  const el = document.getElementById(id);
  return el ? (el.value || "").trim() : "";
}

